{"function":"async () => {
  const asins = ['B07RP9K6KV', 'B01LVXOCU2', 'B0F2TJ7ZL7', 'B0F7LW38FX', 'B07F295DPC', 'B0F1TZ114W', 'B00SMEENOU', 'B00SMEEVC4'];
  const results = {};
  for (const asin of asins) {
    try {
      const res = await fetch(`https://www.amazon.com/dp/${asin}`, { headers: { 'Accept': 'text/html' } });
      if (!res.ok) {
        results[asin] = { status: res.status };
        continue;
      }
      const text = await res.text();
      const parser = new DOMParser();
      const doc = parser.parseFromString(text, 'text/html');

      const title = doc.querySelector('#productTitle')?.innerText?.trim() || doc.querySelector('title')?.innerText?.trim();
      const rating = doc.querySelector('#acrPopover')?.getAttribute('title') || doc.querySelector('.a-icon-star-small .a-icon-alt')?.innerText;
      const reviewCount = doc.querySelector('#acrCustomerReviewText')?.innerText?.trim();
      const price = doc.querySelector('.a-price .a-offscreen')?.innerText || doc.querySelector('#priceblock_ourprice')?.innerText;
      const buyboxUnavailable = !!doc.querySelector('#outOfStock, #availability .a-color-price, #buybox-see-all-buying-choices');

      results[asin] = {
        title: title ? title.slice(0, 80) : null,
        rating,
        reviewCount,
        price,
        buyboxUnavailable
      };
    } catch (e) {
      results[asin] = { error: e.message };
    }
  }
  return results;
}","pageId":1,"toolSummary":"Check ASIN product pages via fetch","waitForStableDom":false}

