            competitionState {
              buyBoxPrice {
                price {
                  amount
                  currencySymbol
                }
              }
              lowestPrice {
                price {
                  amount
                  currencySymbol
                }
              }
              salesRank {
                rank
                productCategory
              }
            }
          }
        }
      }
    }
  `;

  const skus = [
